label.source:
// A short label in the work's type with a paper-coloured halo, so it stays legible over
// pictures and lines. Lines break at "\n"; an optional note sits underneath, smaller.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const size = Number(d.size ?? 16);
const align = d.align ?? "center";
const x = align === "start" ? 0 : align === "end" ? W : W / 2;
const anchor = align === "center" ? "middle" : align;
const esc = (s) =>
  String(s).replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const lines = String(d.text ?? "").split("\n");
const note = d.note ? String(d.note).split("\n") : [];
const noteSize = size * 0.78;
const total = lines.length * size * 1.25 + note.length * noteSize * 1.3;
let y = (H - total) / 2 + size * 0.95;
const halo =
  d.halo === false
    ? ""
    : `paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="${Math.max(3, size / 4)}" stroke-linejoin="round"`;
const rows = [];
for (const line of lines) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${size}" font-weight="${d.weight ?? 500}" fill="${d.color || t.ink || "#222"}" ${halo}>${esc(line)}</text>`,
  );
  y += size * 1.25;
}
for (const line of note) {
  rows.push(
    `<text x="${x}" y="${y}" text-anchor="${anchor}" font-size="${noteSize}" fill="${d.noteColor || t.muted || "#777"}" ${halo}>${esc(line)}</text>`,
  );
  y += noteSize * 1.3;
}
return api.svg(
  `<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible" font-family="${esc(t.font || "system-ui")}">${rows.join("")}</svg>`,
);

node.source:
// A block of a flowchart, architecture or concept map: a shape holding a title, an
// optional note and an optional icon picture, coloured by the style's tokens. Place one per
// module and join them with arrow links, so each block moves on its own and its
// connections follow. The words are HTML, so they wrap inside the shape.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const esc = (s) =>
  String(s ?? "").replace(
    /[&<>"]/g,
    (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
  );
const ink = t.ink || "#222",
  paper = t.paper || "#fff",
  muted = t.muted || "#888";
const tones = {
  plain: muted,
  accent: t.accent || "#d97757",
  accent2: t.accent2 || t.accent || "#4f7c8a",
  muted,
  ink,
};
const tone = tones[d.tone] ? d.tone : "plain";
const color = d.color || tones[tone];
const fill = d.fillStyle || (tone === "plain" ? "none" : "soft");
const sw = Math.max(1, Number(t.stroke ?? 1.6) * 0.85);
const shape = d.shape || "box";
const size = Number(d.size ?? 15);
const s = sw / 2 + 0.5;
const iw = W - 2 * s,
  ih = H - 2 * s;
// The shape, and the part of it that words may use.
let path,
  extra = "",
  inset = { l: size * 0.9, r: size * 0.9, t: size * 0.55, b: size * 0.55 };
if (shape === "pill" || shape === "circle") {
  const rx = shape === "circle" ? iw / 2 : Math.min(iw, ih) / 2,
    ry = shape === "circle" ? ih / 2 : rx;
  path = `<rect x="${s}" y="${s}" width="${iw}" height="${ih}" rx="${rx}" ry="${ry}"/>`;
  if (shape === "circle")
    inset = { l: W * 0.15, r: W * 0.15, t: H * 0.15, b: H * 0.15 };
  else inset = { ...inset, l: rx * 0.6 + size * 0.4, r: rx * 0.6 + size * 0.4 };
} else if (shape === "diamond") {
  path = `<path d="M${W / 2} ${s}L${W - s} ${H / 2}L${W / 2} ${H - s}L${s} ${H / 2}Z" stroke-linejoin="round"/>`;
  inset = { l: W * 0.24, r: W * 0.24, t: H * 0.22, b: H * 0.22 };
} else if (shape === "cylinder") {
  const ry = Math.min(ih * 0.14, iw * 0.12, 16);
  path = `<path d="M${s} ${s + ry}A${iw / 2} ${ry} 0 0 1 ${W - s} ${s + ry}V${H - s - ry}A${iw / 2} ${ry} 0 0 1 ${s} ${H - s - ry}Z"/>`;
  extra = `<path d="M${s} ${s + ry}A${iw / 2} ${ry} 0 0 0 ${W - s} ${s + ry}" fill="none"/>`;
  inset = { ...inset, t: ry * 2 + size * 0.3, b: ry + size * 0.4 };
} else if (shape === "document") {
  const wave = Math.min(ih * 0.1, 10),
    r = Math.min(10, ih * 0.15);
  path = `<path d="M${s + r} ${s}H${W - s - r}Q${W - s} ${s} ${W - s} ${s + r}V${H - s - wave}C${W * 0.75} ${H - s - wave * 3} ${W * 0.5} ${H - s + wave * 0.6} ${s} ${H - s - wave * 0.6}V${s + r}Q${s} ${s} ${s + r} ${s}Z" stroke-linejoin="round"/>`;
  inset = { ...inset, b: wave * 2 + size * 0.4 };
} else {
  const rx = Math.min(Number(d.radius ?? 10), ih / 2);
  path = `<rect x="${s}" y="${s}" width="${iw}" height="${ih}" rx="${rx}"/>`;
}
const fills = {
  solid: `fill="${color}" stroke="${color}"`,
  soft: `fill="${color}" fill-opacity=".14" stroke="${color}"`,
  none: `fill="${paper}" stroke="${color}"`,
};
const shade = d.lift
  ? `<filter id="lift" x="-20%" y="-20%" width="140%" height="160%"><feDropShadow dx="0" dy="${size * 0.18}" stdDeviation="${size * 0.3}" flood-color="${ink}" flood-opacity=".16"/></filter>`
  : "";
const effect = d.effect ? ` filter="${api.effect(d.effect)}"` : "";
const solid = fill === "solid";
const root = api.html(`<style>
:host,.node{position:relative;width:${W}px;height:${H}px}
svg{position:absolute;inset:0;overflow:visible}
.words{position:absolute;left:${inset.l}px;right:${inset.r}px;top:${inset.t}px;bottom:${inset.b}px;display:flex;flex-direction:${d.icon && W < H * 1.6 ? "column" : "row"};align-items:center;justify-content:center;gap:${size * 0.55}px;font-family:${esc(t.font || "system-ui")};text-align:${d.align === "left" ? "left" : "center"};color:${solid ? paper : ink}}
.text{display:flex;flex-direction:column;gap:${size * 0.18}px;min-width:0;${d.align === "left" ? "flex:1;" : ""}}
.title{font-size:${size}px;font-weight:${d.weight ?? 600};line-height:1.25;overflow-wrap:anywhere;text-wrap:balance}
.note{font-size:${size * 0.8}px;line-height:1.3;color:${solid ? paper : muted};opacity:${solid ? 0.85 : 1};overflow-wrap:anywhere;text-wrap:balance}
.icon{flex:none;display:flex}
</style><div class="node"><svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">${shade}<g ${fills[fill] || fills.none} stroke-width="${sw}"${d.lift ? ' filter="url(#lift)"' : ""}${effect}>${path}${extra}</g></svg><div class="words"><div class="text">${d.title ? `<div class="title">${esc(d.title)}</div>` : ""}${d.note ? `<div class="note">${esc(d.note)}</div>` : ""}</div></div></div>`);
if (d.dashed)
  root
    .querySelector("g")
    .setAttribute("stroke-dasharray", `${sw * 4} ${sw * 3}`);
if (d.icon && api.materials[d.icon]) {
  const box = Math.min(
    (H - inset.t - inset.b) * (W < H * 1.6 ? 0.55 : 0.9),
    W * 0.4,
    size * 3.4,
  );
  const slot = document.createElement("div");
  slot.className = "icon";
  slot.append(
    api.material(d.icon, {
      width: box,
      height: box,
      align: "center",
      ...(solid ? { color: paper } : { color }),
    }),
  );
  root.querySelector(".words").prepend(slot);
}
return root;

arrow.source:
// An arrow with a head sized to its line, between api.from and api.to (as a link) or
// between data.from and data.to (normalized points of the module). It runs as a curve
// (straight unless bent), or at right angles as flowcharts do: elbow leaves and arrives
// along the sides its ends meet, corner turns once; both step straight out of a module
// before turning and go round when the ends face away.
const d = api.data,
  t = api.theme;
const W = api.width,
  H = api.height;
const w = Number(d.width ?? t.stroke ?? 1.6);
const color = d.color || t.ink || "#333";
const at = (p, fallback) => (p ? { x: p.x * W, y: p.y * H } : fallback);
let a = api.from ?? at(d.from, { x: 0, y: H / 2 });
let b = api.to ?? at(d.to, { x: W, y: H / 2 });
const len = Math.hypot(b.x - a.x, b.y - a.y) || 1;
const ux = (b.x - a.x) / len,
  uy = (b.y - a.y) / len;
const head = d.head ?? "filled";
const hl = Math.max(7, w * 4.2),
  hw = hl * 0.42;
const away = (p, q) => {
  const l = Math.hypot(p.x - q.x, p.y - q.y) || 1;
  return { x: (p.x - q.x) / l, y: (p.y - q.y) / l };
};
const tip = (p, dir) => {
  const back = { x: p.x - dir.x * hl, y: p.y - dir.y * hl };
  const side = { x: -dir.y * hw, y: dir.x * hw };
  if (head === "open")
    return `<path d="M${back.x + side.x} ${back.y + side.y}L${p.x} ${p.y}L${back.x - side.x} ${back.y - side.y}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
  const notch = { x: p.x - dir.x * hl * 0.78, y: p.y - dir.y * hl * 0.78 };
  return `<path d="M${p.x} ${p.y}L${back.x + side.x} ${back.y + side.y}L${notch.x} ${notch.y}L${back.x - side.x} ${back.y - side.y}Z" fill="${color}" stroke="${color}" stroke-width="${w * 0.5}" stroke-linejoin="round"/>`;
};
// The line stops inside a filled head instead of poking through its point.
const pull = head === "filled" ? hl * 0.7 : 0;
const back = (p, dir, by) => ({ x: p.x - dir.x * by, y: p.y - dir.y * by });
const route = d.route ?? "curve";
// end and start point out of the line at each end; mid and normal place the label.
let line, end, start, mid, normal;
if (route === "elbow" || route === "corner") {
  const dx = b.x - a.x,
    dy = b.y - a.y;
  // Each end runs along the side its anchor faces, else along the given or longer axis.
  const axis = (side) =>
    side === "left" || side === "right"
      ? "h"
      : side === "top" || side === "bottom"
        ? "v"
        : null;
  const other = (x) => (x === "h" ? "v" : "h");
  const given =
    d.first === "horizontal" ? "h" : d.first === "vertical" ? "v" : null;
  const leave =
    given ??
    axis(api.fromSide) ??
    axis(api.toSide) ??
    (Math.abs(dx) >= Math.abs(dy) ? "h" : "v");
  const arrive =
    route === "corner"
      ? other(leave)
      : given
        ? leave
        : (axis(api.toSide) ?? leave);
  const k = 0.5 + Number(d.bend ?? 0);
  // A line first runs this far straight out of the side it leaves, and into the side it
  // arrives at, before it turns, so it never turns on a module's edge or runs back
  // through the module.
  const STUB = 24;
  // The way out of a module through an end's side along an axis: 1, -1, or 0 when the
  // end is not on a side across that axis.
  const out = (side, ax) =>
    ax === "h"
      ? side === "right" ? 1 : side === "left" ? -1 : 0
      : side === "bottom" ? 1 : side === "top" ? -1 : 0;
  // Points given by their coordinate along an axis and across it.
  const at = (ax, along, across) =>
    ax === "h" ? { x: along, y: across } : { x: across, y: along };
  const ak = leave === "h" ? "x" : "y",
    ck = leave === "h" ? "y" : "x";
  const fo = out(api.fromSide, leave),
    to = out(api.toSide, arrive);
  let pts;
  if (leave !== arrive) {
    // One turn, where the line leaves along one axis and arrives along the other, as long
    // as it moves out of both modules; otherwise it steps out of each and goes round.
    const leaves = fo === 0 || fo * (b[ak] - a[ak]) >= STUB,
      arrives = to === 0 || to * (a[ck] - b[ck]) >= STUB;
    if (leaves && arrives) pts = [a, at(leave, b[ak], a[ck]), b];
    else {
      const s = at(leave, a[ak] + fo * STUB, a[ck]),
        e = at(leave, b[ak], b[ck] + to * STUB);
      pts = [a, s, at(leave, s[ak], e[ck]), e, b];
    }
  } else {
    // A cross segment between two runs along one axis: bend places it between the ends,
    // and it stays out of the modules the line leaves and arrives at.
    const want = a[ak] + (b[ak] - a[ak]) * k;
    let lo = -Infinity,
      hi = Infinity;
    if (fo > 0) lo = Math.max(lo, a[ak] + STUB);
    if (fo < 0) hi = Math.min(hi, a[ak] - STUB);
    if (to > 0) lo = Math.max(lo, b[ak] + STUB);
    if (to < 0) hi = Math.min(hi, b[ak] - STUB);
    const ahead =
      (fo === 0 || fo * (b[ak] - a[ak]) > 0) &&
      (to === 0 || to * (a[ak] - b[ak]) > 0);
    if (lo <= hi || ahead) {
      // Ends facing each other closer than two steps keep the cross segment between them.
      const c =
        lo <= hi
          ? Math.min(hi, Math.max(lo, want))
          : Math.min(Math.max(a[ak], b[ak]), Math.max(Math.min(a[ak], b[ak]), want));
      pts = [a, at(leave, c, a[ck]), at(leave, c, b[ck]), b];
    } else {
      // Back to back: out of each, across between them, and in.
      const m = a[ck] + (b[ck] - a[ck]) * k,
        c1 = a[ak] + fo * STUB,
        c2 = b[ak] + to * STUB;
      pts = [a, at(leave, c1, a[ck]), at(leave, c1, m), at(leave, c2, m), at(leave, c2, b[ck]), b];
    }
  }
  // Ends already in line need no turn: repeated points and straight-through ones go.
  const kept = [];
  for (const p of pts) {
    const last = kept[kept.length - 1];
    if (!last || Math.hypot(p.x - last.x, p.y - last.y) > 0.5) kept.push(p);
    else if (p === b) kept[kept.length - 1] = p;
  }
  pts = kept.filter((p, i) => {
    if (i === 0 || i === kept.length - 1) return true;
    const q = kept[i - 1],
      r = kept[i + 1];
    return (
      Math.abs((p.x - q.x) * (r.y - p.y) - (p.y - q.y) * (r.x - p.x)) > 0.5
    );
  });
  if (pts.length < 2) pts = [a, b];
  const n = pts.length;
  end = away(pts[n - 1], pts[n - 2]);
  start = away(pts[0], pts[1]);
  const first = Math.hypot(pts[1].x - pts[0].x, pts[1].y - pts[0].y),
    last = Math.hypot(pts[n - 1].x - pts[n - 2].x, pts[n - 1].y - pts[n - 2].y);
  const gap = Math.min(Number(d.gap ?? 6), first / 3, last / 3);
  pts[0] = back(pts[0], start, gap);
  pts[n - 1] = back(pts[n - 1], end, gap);
  a = pts[0];
  b = pts[n - 1];
  const drawn = [...pts];
  if (head !== "none") drawn[n - 1] = back(b, end, pull);
  if (d.both && head !== "none") drawn[0] = back(a, start, pull);
  // Corners rounded by up to radius, never more than half of either segment.
  const r = Number(d.radius ?? 10);
  line = `M${drawn[0].x} ${drawn[0].y}`;
  for (let i = 1; i < n - 1; i++) {
    const p = drawn[i],
      inn = away(drawn[i - 1], p),
      out = away(drawn[i + 1], p);
    const lin = Math.hypot(p.x - drawn[i - 1].x, p.y - drawn[i - 1].y),
      lout = Math.hypot(drawn[i + 1].x - p.x, drawn[i + 1].y - p.y);
    const rr = Math.min(r, lin / 2, lout / 2);
    line += `L${p.x + inn.x * rr} ${p.y + inn.y * rr}Q${p.x} ${p.y} ${p.x + out.x * rr} ${p.y + out.y * rr}`;
  }
  line += `L${drawn[n - 1].x} ${drawn[n - 1].y}`;
  // The label sits beside the longest segment.
  let best = 1;
  for (let i = 1; i < n; i++)
    if (
      Math.hypot(pts[i].x - pts[i - 1].x, pts[i].y - pts[i - 1].y) >
      Math.hypot(pts[best].x - pts[best - 1].x, pts[best].y - pts[best - 1].y)
    )
      best = i;
  const p = pts[best - 1],
    q = pts[best],
    l = Math.hypot(q.x - p.x, q.y - p.y) || 1;
  mid = { x: (p.x + q.x) / 2, y: (p.y + q.y) / 2 };
  normal = { x: -(q.y - p.y) / l, y: (q.x - p.x) / l };
} else {
  const gap = Math.min(Number(d.gap ?? 6), len / 4);
  a = { x: a.x + ux * gap, y: a.y + uy * gap };
  b = { x: b.x - ux * gap, y: b.y - uy * gap };
  const bend = Number(d.bend ?? 0) * len;
  const c = {
    x: (a.x + b.x) / 2 - uy * bend,
    y: (a.y + b.y) / 2 + ux * bend,
  };
  end = away(b, c);
  start = away(a, c);
  const b2 = head === "none" ? b : back(b, end, pull);
  const a2 = d.both && head !== "none" ? back(a, start, pull) : a;
  line = `M${a2.x} ${a2.y}Q${c.x} ${c.y} ${b2.x} ${b2.y}`;
  mid = { x: (a.x + 2 * c.x + b.x) / 4, y: (a.y + 2 * c.y + b.y) / 4 };
  normal = { x: -uy, y: ux };
}
const dash = d.flow
  ? `${w * 3} ${w * 2.6}`
  : d.dashed
    ? `${w * 4} ${w * 3}`
    : "none";
const flow = d.flow
  ? `<style>@keyframes flow{to{stroke-dashoffset:${-w * 5.6 * 4}}}.flow{animation:flow ${Number(d.speed ?? 1.2)}s linear infinite}</style>`
  : "";
let label = "";
if (d.label) {
  const size = Number(d.size ?? 16);
  const m = mid;
  let n = normal;
  const above = (d.labelSide ?? "above") === "above";
  if ((n.y > 0.2 || (Math.abs(n.y) <= 0.2 && n.x > 0)) === above)
    n = { x: -n.x, y: -n.y };
  // Beside an upright line the words start at the line, as they are wider than they are tall.
  const upright = Math.abs(n.x) > 0.8;
  const off = upright ? size * 0.5 + w : size * 0.9 + w;
  const esc = (s) =>
    String(s).replace(
      /[&<>"]/g,
      (ch) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;" })[ch],
    );
  label = `<text x="${m.x + n.x * off}" y="${m.y + n.y * off}" text-anchor="${upright ? (n.x > 0 ? "start" : "end") : "middle"}" dominant-baseline="central" font-size="${size}" fill="${d.labelColor || color}" font-family="${esc(t.font || "system-ui")}" paint-order="stroke" stroke="${t.paper || "#fff"}" stroke-width="4" stroke-linejoin="round">${esc(d.label)}</text>`;
}
return api.svg(`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}" style="overflow:visible">${flow}
  <path class="${d.flow ? "flow" : ""}" d="${line}" fill="none" stroke="${color}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round" stroke-dasharray="${dash}"/>
  ${head === "none" ? "" : tip(b, end)}${d.both && head !== "none" ? tip(a, start) : ""}${label}
</svg>`);

chart.source:
// 一张海图上的“两线定位”：两座灯塔各按自己的灯质闪；船上的人认出第一座，测方位，
// 在海图上画一条线；再认出第二座，再画一条——两条线相交的地方就是船。一轮演示一遍，
// 每走到一步就发出 step 事件，旁边的流程图跟着亮起对应的那一格。
const { width: W, height: H, data: d, theme: t } = api;
const ink = t.ink,
  muted = t.muted;
const flare = "#c2387e",
  land = "#efe4c4",
  water = "#e8f1f5";
const A = { x: d.a[0], y: d.a[1] },
  B = { x: d.b[0], y: d.b[1] },
  S = { x: d.ship[0], y: d.ship[1] };
const esc = (s) => String(s).replace(/[&<>]/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;" })[c]);
// 方位：从船看灯塔的真方位（北为 0°，顺时针）
const bearing = (L) => Math.round(((Math.atan2(L.x - S.x, -(L.y - S.y)) * 180) / Math.PI + 360) % 360);
const through = (L, f) => {
  const dx = S.x - L.x,
    dy = S.y - L.y,
    n = Math.hypot(dx, dy);
  return [L.x + (dx / n) * n * f, L.y + (dy / n) * n * f];
};
const coast = `M0 0 H${W} V${H * 0.12} C${W * 0.86} ${H * 0.16} ${W * 0.8} ${H * 0.1} ${B.x + 30} ${B.y + 18}
  C${B.x - 10} ${B.y + 34} ${W * 0.62} ${H * 0.3} ${W * 0.5} ${H * 0.27} C${W * 0.4} ${H * 0.24} ${W * 0.34} ${H * 0.36} ${A.x + 46} ${A.y + 6}
  C${A.x + 10} ${A.y + 26} ${A.x - 30} ${A.y + 14} 0 ${A.y + 40} Z`;
const contour = (k) =>
  `M0 ${A.y + 70 + k * 46} C${W * 0.25} ${A.y + 50 + k * 50} ${W * 0.42} ${H * 0.36 + k * 52} ${W * 0.6} ${H * 0.34 + k * 50} S${W * 0.9} ${H * 0.2 + k * 48} ${W} ${H * 0.18 + k * 48}`;
const soundings = [
  [60, 330, 8],
  [150, 380, 14],
  [330, 300, 11],
  [420, 360, 19],
  [90, 470, 22],
  [380, 470, 27],
  [200, 540, 31],
  [430, 560, 36],
  [300, 210, 6],
];
const rose = { x: 74, y: H - 86, r: 50 };

const svg = api.svg(`<svg viewBox="0 0 ${W} ${H}" width="${W}" height="${H}">
  <defs>
